def simulate_snake(board_size, snake, food, moves):
    width, height = board_size

    # Helper to validate coordinates
    def valid_pos(x, y):
        return 0 <= x < width and 0 <= y < height

    # Helper to check head collision with body (except tail)
    def collide_with_body(head_x, head_y, snake_body):
        if not valid_pos(head_x, head_y):
            return True
        for part in snake_body[:-1]:
            if head_x == part[0] and head_y == part[1]:
                return True
        return False

    food_eaten_count = 0
    direction_map = {
        "UP": (-1, 0),
        "DOWN": (1, 0),
        "LEFT": (0, -1),
        "RIGHT": (0, 1)
    }
    snake_directions = {"UP", "DOWN", "LEFT", "RIGHT"}

    last_direction = None
    tail_index = len(snake) - 1

    for move in moves:
        dx, dy = direction_map.get(move, (0, 0))

        # Prevent reversing current direction
        if last_direction is not None:
            prev_dx, prev_dy = direction_map[last_direction]
            if (dx == -prev_dx and dy == -prev_dy):
                continue

        new_head_x, new_head_y = snake[0][0] + dx, snake[0][1] + dy

        # Check if head is about to hit its own body or go out of bounds
        if collide_with_body(new_head_x, new_head_y, snake):
            break

        # Move snake forward (remove tail unless just ate)
        will_eat = False
        if food and food[0] == (new_head_x, new_head_y):
            will_eat = True
            food.pop(0)
            food.append(None)
            food_eaten_count += 1

        # Grow snake if eating
        new_snake = [snake[0]] + snake[:-1] + ([new_head_x, new_head_y] if not will_eat else snake[-1])
        if will_eat:
            new_snake.append(snake[-1])
        else:
            new_snake.pop()

        # Update snake and direction
        snake = new_snake
        last_direction = move
        tail_index += 1

    alive = len(food) > 0 or food_eaten_count < len(moves) if moves else True
    return (snake, alive, food_eaten_count)
